  "aiworkspace.presentation.start.writerLive": "أثناء العرض، هذا المكان العمل مغلق لكي لا يتم كتابة المحتوى من قبل الآخرين أو من خلال نافذاتك الأخرى؛ يمكن كتابة السير الذاتية بعد انتهاء العرض. المسار يحتوي على أجزاء “قابلة للتشغيل أثناء العرض”: العمليات الحية تُكتب في نسخة مؤقتة تُحذف تلقائيًا بعد انتهاء العرض، مما يترك النسخة الأصلية دون تغيير.",
