  "aiworkspace.demo.film.howto.title": "سيرفر العملية القصيرة للذكاء الاصطناعي: ملفات الشخصيات → رسومات الشخصيات → مخطط القصة → المونتاج النهائي",
  "aiworkspace.demo.film.howto.text": "تدفق توليد البيانات من اليسار إلى اليمين، حيث كل عقدة تمثل كائنًا عاديًا: على اليسار توجد السكريبت وقائمة الأحرف والأسلوب التي يمكن تعديلها مباشرة؛ كل مرحلة تمثل كتلة، وعلى كل بطاقة يمكنك الضغط على Analyze، Write macro، وRun macro بالتتابع – كل خطوة تكتب نتائجها بمجرد اكتمالها. ما ينتج عن إحدى المراحل يصبح مدخلًا لمرحلة أخرى، لذا يجب تشغيل المراحل من اليسار إلى اليمين؛ الأشعة الزرقاء تشير من ما تم توليده، والأشعة البرتقالية تشير إلى ما تم إنشاؤه. إذا قمت بتغيير قائمة الأحرف أو السكريبت، فإن النتائج النهائية ستكون غير محدثة؛ قم بتشغيلها مرة أخرى واحدة تلو الأخرى. الصور والفيديوهات تم إنشاؤها بواسطة نماذج الذكاء الاصطناعي في Zone.",
